class Solution {
public:
    long long taskSchedulerII(std::vector<int>& tasks, int space) {
        long long cur_day = 0;
        std::unordered_map<int, long long> last_done;
        for (int t : tasks) {
            if (last_done.count(t)) {
                cur_day = std::max(cur_day + 1, last_done[t] + space + 1);
            } else {
                cur_day++;
            }
            last_done[t] = cur_day;
        }
        return cur_day;
    }
};

class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        long curDay = 0;
        java.util.Map<Integer, Long> lastDone = new java.util.HashMap<>();
        for (int t : tasks) {
            if (lastDone.containsKey(t)) {
                curDay = Math.max(curDay + 1, lastDone.get(t) + space + 1);
            } else {
                curDay++;
            }
            lastDone.put(t, curDay);
        }
        return curDay;
    }
}

var taskSchedulerII = function(tasks, space) {
    let curDay = 0n;
    const spaceBig = BigInt(space);
    const lastDone = new Map();
    for (const t of tasks) {
        if (lastDone.has(t)) {
            const minValid = lastDone.get(t) + spaceBig + 1n;
            curDay = curDay + 1n > minValid ? curDay + 1n : minValid;
        } else {
            curDay += 1n;
        }
        lastDone.set(t, curDay);
    }
    return Number(curDay);
};
